// NewOperatorNodeClient returns a client for the OperatorNode from the given config.
func NewOperatorNodeClient(c config) *OperatorNodeClient {
	return &OperatorNodeClient{config: c}
}

// Use adds a list of mutation hooks to the hooks stack.
// A call to `Use(f, g, h)` equals to `operatornode.Hooks(f(g(h())))`.
func (c *OperatorNodeClient) Use(hooks ...Hook) {
	c.hooks.OperatorNode = append(c.hooks.OperatorNode, hooks...)
}

// Intercept adds a list of query interceptors to the interceptors stack.
// A call to `Intercept(f, g, h)` equals to `operatornode.Intercept(f(g(h())))`.
func (c *OperatorNodeClient) Intercept(interceptors ...Interceptor) {
	c.inters.OperatorNode = append(c.inters.OperatorNode, interceptors...)
}

// Create returns a builder for creating a OperatorNode entity.
func (c *OperatorNodeClient) Create() *OperatorNodeCreate {
	mutation := newOperatorNodeMutation(c.config, OpCreate)
	return &OperatorNodeCreate{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// CreateBulk returns a builder for creating a bulk of OperatorNode entities.
func (c *OperatorNodeClient) CreateBulk(builders ...*OperatorNodeCreate) *OperatorNodeCreateBulk {
	return &OperatorNodeCreateBulk{config: c.config, builders: builders}
}

// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *OperatorNodeClient) MapCreateBulk(slice any, setFunc func(*OperatorNodeCreate, int)) *OperatorNodeCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &OperatorNodeCreateBulk{err: fmt.Errorf("calling to OperatorNodeClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*OperatorNodeCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &OperatorNodeCreateBulk{config: c.config, builders: builders}
}

